enum { MAX_GOALS_PER_LEVEL = 5, MAX_PREV_LEVELS = 4, MAX_NEXT_LEVELS = 2, LEVEL_LAST = 32 };
typedef struct CareerDataStruct {
    int beach;
    int goal_param[5];
    int reward_param[5];
    char beach_file[32];
    char name[32];
    int goal[5];
    int goal_param_2[5];
    int reward[5];
    int prev_levels[4];
    int next_levels[2];
    float level_duration;
    char stash_name[15];
    int use_ai_surfer;
    char challenge_name[32];
} CareerData;
extern CareerData CareerDataArray[];
__asm__(".equ CareerDataArray, 0x0042ECA0");

class Career {
public:
    class Level {
        int my_id;
        bool is_new;
        bool advanced;
        bool unlocked;
        bool goals[MAX_GOALS_PER_LEVEL];
    public:
        void Unlock(void);
        bool IsGoalDone(const int goalIdx) const;
    };
private:
    char prefix[0x1019c];
public:
    Level levels[LEVEL_LAST];
protected:
    bool IsAdvanceGoalDone(const int levelIdx) const { return levels[levelIdx].IsGoalDone(0); }
    void CheckUnlockNextLevels(const int levelIdx);
};
__asm__(".equ Unlock__Q26Career5Level, 0x0025C3A8");
__asm__(".equ IsGoalDone__CQ26Career5Leveli, 0x0025C418");

void Career::CheckUnlockNextLevels(const int levelIdx)
{
	int i, j;
	int next_level, prev_level;
	//int level_index;
	bool level_open;

	// For every level that comes after this one, check to see if _that_ 
	// level's prerequisites have been completed.  If so, unlock that level.
	for(i = 0; i < MAX_NEXT_LEVELS; i++)
	{
		next_level = CareerDataArray[levelIdx].next_levels[i];
		level_open = true;
		if(next_level != -1)
		{
			// Check whether all this level's previous entries have had their advance goal completed
			for(j = 0; j < MAX_PREV_LEVELS; j++)
			{
				prev_level = CareerDataArray[next_level].prev_levels[j];
				if(prev_level != -1 && !IsAdvanceGoalDone(prev_level))
					level_open = false;
			}
			// If all the previous levels have been completed then unlock this level
			if(level_open)
				levels[next_level].Unlock();
		}
	}
}
